architecture.h4_f:
msg = CBOR{v:1, sɛbɛnni, jaabi_kalan, ci_se}
ct = AES-GCM-256-Kɔrɔsili (k, nonce, msg, aad=so_id)
POST /api/so/{id}/cikanw {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, sɛbɛnni, jaabi_ka?, dilan_id?, kofɔli?, ci_ka}
ct = AES-GCM-256-Encrypt(so_kɔlɔsili, nonce, pt, aad=hex(so_id))
nɛgɛ = CBOR{
  v: 1, 1 .
  ciphertext: hex(ct), // janya caman ɲɔgɔnna
  nonce: hɛkɛsi(12 B), .
  ciden_ka_ko: hex(16 B), .
  ci_yɔrɔ: unix_ms
} .

auth.h3_f:
access_token nafamafɛnw:
  { sub: baarakɛla_id, jti: minɛn_id, typ: "sɔrɔ", exp: sisan + 15min }
refresh_token nafamafɛnw:
  { sub: baarakɛla_id, jti: minɛn_id, typ: "lakura", exp: sisan + 30d }

HS256-bolonɔbila ni node ka 64-byte gundo ye ka bɔ .env

rooms.h6_f:
ciden_nɔgɔ = HMAC-SHA256(so_kɔgɔ_nɔgɔlen, ciden_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(so_kɔlɔsili, nonce, CBOR_payload, aad=so_id)

Fan-out frame: { suguya:"m", so, msg:{id, ct, nonce, ciden_pseudo, ci_ka} }

files.h2_f:
init POST /api/files/resumible/init {dosiyɛri tɔgɔ, a bonya, chunk_size_hint}
            ← {upload_id, chunk_size} Bamako, Mali.
chunk PUT /api/dosiyɛriw/segin-ka-bɔ/{upload_id}/chunk/{offset} <ct bytes>
            ← 204. Ɲɛjirali dɔw
laban POST /api/dosiyɛriw/segin-ka-bɔ/{upload_id}/finalize {plain_blake3}
            ← 201 {dosiyɛri_id, url}
TTL kan min ma ban: 24 h

files.h4_f:
deny_list = {
  "application/x-dosexec" ye.
  "application/x-sharedlib",
