apns.h1_f:
POST https://api.push.apple.com/3/minɛn/<minɛn_taamaʃyɛn>
Kungolow: apns-kunnafoni: <bundle_id>, apns-push-suguya: lasɔmini, apns-collapse-id: so:42
Farikolo: {aps: {kɔlɔsili: {titre, farikolo}}, data: <sɔgɔlen>}

bmp.h1_f:
mailbox_id = HKDF(sɔrɔbaga_pubkey, kunnafoni="bmp-v1", len=32)
Deposit: POST /bmp/deposit {mailbox_id, blob ≤1MB}
Pickup: GET /bmp/cikanw (sɛbɛnni)

controller.h1_f:
GET /v1/integrity → {status, signed_by, bɛnkan, bɛnbaliya, ...}
GET /v1/kɛnɛya → {status, version, pubkey, statis}
GET /v1/sɛbɛnw → [{protocol, url}, ...]
GET /v1/miroirs → [kɔlɔsilikɛla_url, ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/porozew/<poroze>/cikanw:ci
Ladilikan: Tabaga <oauth2_token>
Farikolo: {cikan: {token: <minɛn>, data: {...sigilen...}, android: {collapse_key}}}

federation.h1_f:
enveloppe = {source_node, laɲini_baarakɛla, kɔnɔna_ct, kɔnɔna_nonce, cilen_at}
sig = Ed25519-Sign(source_priv, CBOR(anwɛlɛki))
POST /federasiyɔn/lase {anwɛlɛki, sig}
B bɛ sɛgɛsɛgɛli kɛ: sig ka kɛlɛ kɛ federasɔn[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE cikanw_fts USING fts5(
  kɔnɔkow, -- tokenised koloma
  so_dakun UNINDEXED,
  tokenize = 'unicode61 bɔ_daɲɛgafe 2'.
);
ɲininkali: SELECT rowid FROM cikanw_fts WHERE kɔnɔkow MATCH 'foo'.

